for (const n in SP) { // saiz ikut peringkat
  const s = SP[n]; let stage = 1, p = s.pre; while (p) { stage++; p = SP[p].pre; }
  let total = stage, q = s; while (q.evos.length) { q = SP[q.evos[0].to]; total++; }
  s.k = total === 1 ? .95 : total === 2 ? (stage === 1 ? .78 : 1) : [.7, .86, 1][stage - 1];
  if (s.cr <= 3) s.k = 1.05;
}

